import requests
import time
import sys

BASE = 'https://snail.racecraft.cf'
SESSION = requests.Session()


def get_money():
    r = SESSION.get(BASE+'/check')
    data = r.json()
    if 'money' in data:
        return int(data['money'])
    return None

def place_bet(side, money):
    url = BASE + f'/bet/{side}'
    data = {'bet':str(money)}
    r = SESSION.patch(url, data=data)
    try:
        result = r.json()
        return result['success'], result.get('error')
    except:
        return False, 'server error'

def wait_for_new_round():
    # Wait/poll until betting is open
    while True:
        r = SESSION.get(BASE+'/check')
        data = r.json()
        start_time = int(data.get('start',0))
        now = int(time.time())
        if now < start_time:
            # betting open, can place
            break
        else:
            # wait until betting reopens
            time.sleep(3)

def trigger_payout():
    r = SESSION.get(BASE+'/check')
    data = r.json()
    return int(data.get('money',0))

def try_get_flag1():
    r = SESSION.get(BASE+'/flag1')
    data = r.json()
    if data.get('success'):
        return data['flag']
    return None

def main():
    print('Starting snailrace auto-grinder...')
    side = 0  # Always bet on Snail A
    money = get_money()
    if money is None:
        print('Could not obtain money! Exiting.')
        sys.exit(1)
    while True:
        wait_for_new_round()
        money = get_money()
        print(f'Current money: {money}')
        if money >= 250000:
            break
        ok, err = place_bet(side, money)
        if not ok:
            print(f'Bet failed: {err}')
            break
        print(f'Bet {money} on Snail {"A" if side==0 else "B"}, waiting for race to finish...')
        time.sleep(13)  # Wait until race likely over
        bal = trigger_payout()
        print(f'After payout: {bal}')
    flag = try_get_flag1()
    print(f'Flag1: {flag}')

if __name__ == '__main__':
    main()

